/**
 * "Blocked by" links between issues. A row reads "`issue_id` is blocked by `blocker_id`".
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { brandId, toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toIssue } from "./_mappers";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { IssueDependencyRow } from "@/server/db";

const CLOSED_STATUSES = ["done", "canceled"] as const;

function toIssueDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: toIsoTimestamp(row.createdAt),
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toIssueDependency(row);
}

/** Resolves `true` when a link was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/** Ids of every issue `issueId` is blocked by, regardless of their state. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

/** Ids of every issue that `blockerId` blocks. */
export async function listBlockedIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.issueId));
}

/** Live blocker issues of `issueId`, ordered by issue number. */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          orgPredicate(issues.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => toIssue(row.issue));
}

/** Blockers of `issueId` that are live and neither `done` nor `canceled`. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          orgPredicate(issues.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_STATUSES]),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => brandId<IssueId>(row.id));
}

/** Drops every link touching one of `issueIds`, in either direction. */
export async function deleteDependenciesForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<void> {
  if (issueIds.length === 0) return;
  getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.issueId, [...issueIds]),
      ),
    )
    .run();
}

