cat > tests/services/zz-scratch-deps.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as dep from "@/server/services/issue-dependency-service";
import * as notificationService from "@/server/services/notification-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("deps", () => {
  it("works", async () => {
    const t = await createTenant("deps");
    const a = t.actors.admin;
    const mk = (title: string) => issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title }));
    const A = await mk("Issue A"); const B = await mk("Issue B"); const C = await mk("Issue C");
    await issueService.assignIssue(a, { orgId: t.org.id, issueId: A.id, assigneeId: t.userIds.member });
    await dep.addBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id });
    const again = await dep.addBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id });
    expect(again.createdBy).toBe(a.userId);
    await dep.addBlocker(a, { orgId: t.org.id, issueId: B.id, blockerId: C.id });
    await expect(dep.addBlocker(a, { orgId: t.org.id, issueId: C.id, blockerId: A.id })).rejects.toThrow();
    await expect(dep.addBlocker(a, { orgId: t.org.id, issueId: C.id, blockerId: C.id })).rejects.toThrow();
    expect((await dep.listBlockers(a, t.org.id, A.id)).map((i) => i.id)).toEqual([B.id]);
    const err = await issueService.moveIssue(a, { orgId: t.org.id, issueId: A.id, toStatus: "done", toIndex: 0 } as never).catch((e) => e);
    expect(err).toBeInstanceOf(dep.IssueBlockedError);
    expect(err.blockerIds).toEqual([B.id]);
    await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: B.id, status: "done" }).catch((e) => { throw e; }).catch(() => {});
    // B is blocked by C, so B done rejected; cancel B instead
    await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: B.id, status: "canceled" });
    const list = await notificationService.listNotifications(t.actors.member, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 50 } as never);
    const n = list.items.filter((x) => x.kind === "issue_unblocked");
    expect(n).toHaveLength(1);
    expect(n[0]).toMatchObject({ href: `/issues/${A.id}`, actorId: a.userId });
    await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: B.id, status: "done" }).catch(() => {});
    await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: A.id, status: "done" });
    expect(await dep.removeBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id })).toBe(true);
    expect(await dep.removeBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id })).toBe(false);
    void notificationRepo;
  });
});
EOF
